  "These are separate applications, not a package requiring every form. FS-240 is the issued certificate, not an application. Complete a separate file for each child and give each parent's details separately. Scans do not replace originals or certified copies at the interview. Follow the embassy's checklist and signature instructions: do not pre-sign DS-2029 or DS-11 when a witnessed signature is required; DS-3053 requires notarization and consent is generally submitted within 90 days. A U.S. address or tax return alone does not prove physical presence. Related-form intake uses the shared questionnaire you provided, not a substitute for official form instructions.": "یہ الگ الگ ایپلی کیشنز ہیں، ہر فارم کی ضرورت کے لیے پیکج نہیں۔ FS-240 جاری کردہ سرٹیفکیٹ ہے، درخواست نہیں۔ ہر بچے کے لیے علیحدہ فائل مکمل کریں اور ہر والدین کی تفصیلات الگ سے دیں۔ انٹرویو میں اسکین اصل یا مصدقہ کاپیوں کی جگہ نہیں لیتے ہیں۔ سفارت خانے کی چیک لسٹ اور دستخطی ہدایات پر عمل کریں: جب گواہی کے دستخط کی ضرورت ہو تو DS-2029 یا DS-11 پر پہلے سے دستخط نہ کریں۔ DS-3053 کو نوٹرائزیشن کی ضرورت ہوتی ہے اور رضامندی عام طور پر 90 دنوں کے اندر جمع کرائی جاتی ہے۔ صرف یو ایس ایڈریس یا ٹیکس ریٹرن جسمانی موجودگی کو ثابت نہیں کرتا ہے۔ متعلقہ فارم انٹیک آپ کے فراہم کردہ مشترکہ سوالنامے کا استعمال کرتا ہے، فارم کی سرکاری ہدایات کا متبادل نہیں۔",
