  "CBP I-94": "CBP I-94",
  "Retrieve your electronic entry record and available travel history. It is a reference tool, not a complete legal record.": "আপনার ইলেকট্রনিক এন্ট্রি রেকর্ড এবং উপলব্ধ ভ্রমণ ইতিহাস পুনরুদ্ধার করুন। এটি একটি রেফারেন্স টুল, একটি সম্পূর্ণ আইনি রেকর্ড নয়।",
  "USCIS — Avoid Scams": "USCIS - কেলেঙ্কারী এড়িয়ে চলুন",
  "Learn to recognize fraud and find authorized legal help.": "জালিয়াতি চিনতে শিখুন এবং অনুমোদিত আইনি সহায়তা পান।",
