  "Document & Photo Toolkit": "ডকুমেন্ট এবং ফটো টুলকিট",
  "Practical utilities to prepare files before uploading. Some features need an account or subscription.": "আপলোড করার আগে ফাইল প্রস্তুত করার জন্য ব্যবহারিক উপযোগিতা। কিছু বৈশিষ্ট্য একটি অ্যাকাউন্ট বা সদস্যতা প্রয়োজন.",
  "Merge & Compress PDF — iLovePDF": "পিডিএফ মার্জ এবং কম্প্রেস করুন — iLovePDF",
  "Merge, split, compress and convert files. Review text and stamp clarity after compressing.": "মার্জ, বিভক্ত, সংকুচিত এবং ফাইল রূপান্তর. সংকুচিত করার পরে পাঠ্য এবং স্ট্যাম্পের স্বচ্ছতা পর্যালোচনা করুন।",
  "PDF Tools — Smallpdf": "পিডিএফ টুলস — Smallpdf",
