  "PDF Tools — Adobe Acrobat Online": "পিডিএফ টুলস — অ্যাডোব অ্যাক্রোব্যাট অনলাইন",
  "Organize, convert and compress PDF files online.": "অনলাইনে পিডিএফ ফাইলগুলি সংগঠিত, রূপান্তর এবং সংকুচিত করুন।",
  "PDF24 Tools": "PDF24 টুল",
  "Free file tools, with a desktop option that processes files locally without uploading them.": "ফ্রি ফাইল টুল, একটি ডেস্কটপ বিকল্পের সাথে যা ফাইলগুলিকে আপলোড না করেই স্থানীয়ভাবে প্রক্রিয়া করে।",
  "E-Signature — DocuSign": "ই-স্বাক্ষর — ডকুসাইন",
  "Send MIGRAFILE contracts and service consents for signature. Check each government form's instructions first — an e-signature is not automatically accepted by USCIS.": "স্বাক্ষরের জন্য MIGRAFILE চুক্তি এবং পরিষেবা সম্মতি পাঠান। প্রতিটি সরকারী ফর্মের নির্দেশাবলী প্রথমে চেক করুন — একটি ই-স্বাক্ষর স্বয়ংক্রিয়ভাবে USCIS দ্বারা গৃহীত হয় না।",
  "E-Signature — Adobe & Smallpdf": "ই-স্বাক্ষর — Adobe & Smallpdf",
  "Fill PDFs and add signatures online.": "PDF পূরণ করুন এবং অনলাইনে স্বাক্ষর যোগ করুন।",
  "Resize Images — iLoveIMG": "চিত্রের আকার পরিবর্তন করুন — iLoveIMG",
  "Change width and height in pixels or percentage. Keep the aspect ratio so faces or documents don't stretch.": "পিক্সেল বা শতাংশে প্রস্থ এবং উচ্চতা পরিবর্তন করুন। আকৃতির অনুপাত রাখুন যাতে মুখ বা নথিগুলি প্রসারিত না হয়।",
  "Compress & Crop — iLoveIMG": "কম্প্রেস এবং ক্রপ — iLoveIMG",
  "Reduce file size in KB/MB or crop a photo. Compress changes size; crop changes framing.": "KB/MB ফাইলের আকার কমিয়ে দিন বা একটি ফটো ক্রপ করুন। সংকুচিত আকার পরিবর্তন; ফসল ফ্রেমিং পরিবর্তন.",
  "iLoveIMG in Arabic": "আরবীতে iLoveIMG",
  "Access the tools with an Arabic interface.": "একটি আরবি ইন্টারফেস দিয়ে টুল অ্যাক্সেস করুন।",
  "Visa Photos — Official Requirements": "ভিসা ফটো - অফিসিয়াল প্রয়োজনীয়তা",
  "Start with the U.S. Department of State's digital photo requirements, including the official photo tool. Resizing alone does not guarantee acceptance.": "অফিসিয়াল ফটো টুল সহ মার্কিন যুক্তরাষ্ট্রের ডিপার্টমেন্ট অফ স্টেটের ডিজিটাল ছবির প্রয়োজনীয়তা দিয়ে শুরু করুন। একা আকার পরিবর্তন গ্রহণযোগ্যতার গ্যারান্টি দেয় না।",
  "MIGRAFILE Tools": "MIGRAFILE টুলস",
  "Official tools & sources": "অফিসিয়াল টুলস এবং সোর্স",
  "Direct links to the official tools for each stage of your case — USCIS, NVC, the embassy, IRS — plus utilities to prepare your documents. MIGRAFILE links to these sources only; it does not operate them.": "আপনার মামলার প্রতিটি পর্যায়ের জন্য অফিসিয়াল টুলগুলির সরাসরি লিঙ্কগুলি — USCIS, NVC, দূতাবাস, IRS — এছাড়াও আপনার নথিগুলি প্রস্তুত করার জন্য ইউটিলিটিগুলি৷ শুধুমাত্র এই উৎসগুলির জন্য MIGRAFILE লিঙ্ক; এটি তাদের পরিচালনা করে না।",
  "These are official external government sources. MIGRAFILE is an independent platform and is not affiliated with USCIS or the U.S. Department of State. Links last reviewed: October 2026.": "এগুলি সরকারী বহিরাগত সরকারী উত্স। MIGRAFILE একটি স্বাধীন প্ল্যাটফর্ম এবং USCIS বা মার্কিন পররাষ্ট্র দপ্তরের সাথে অনুমোদিত নয়। লিঙ্কগুলি সর্বশেষ পর্যালোচনা করা হয়েছে: অক্টোবর 2026।",
  "Open official source": "ওপেন অফিশিয়াল সোর্স",
  "Track my case": "আমার কেস ট্র্যাক",
  "Secure sign-in is required to view any case information. For your protection, cases cannot be looked up by case number alone.": "যেকোনো কেস তথ্য দেখতে নিরাপদ সাইন-ইন প্রয়োজন। আপনার সুরক্ষার জন্য, শুধুমাত্র কেস নম্বর দিয়ে কেসগুলি দেখা যাবে না৷",
