  "MIGRAFILE is a documentation and case-management service. We are not a law firm, do not provide legal advice, and do not recommend visas or predict outcomes.": "MIGRAFILE একটি ডকুমেন্টেশন এবং কেস-ম্যানেজমেন্ট পরিষেবা। আমরা একটি আইন সংস্থা নই, আইনি পরামর্শ প্রদান করি না এবং ভিসা সুপারিশ করি না বা ফলাফলের পূর্বাভাস দিই না।",
  "You choose the form and category yourself, and you remain responsible for the accuracy of all information you provide.": "আপনি নিজেই ফর্ম এবং বিভাগ বেছে নিন এবং আপনার দেওয়া সমস্ত তথ্যের নির্ভুলতার জন্য আপনি দায়ী থাকবেন।",
