  "Choose a service first to see its forms": "এর ফর্মগুলি দেখতে প্রথমে একটি পরিষেবা চয়ন করুন৷",
  "No forms are linked to this service — its documents are collected with you directly.": "এই পরিষেবার সাথে কোনও ফর্ম লিঙ্ক নেই — এর নথিগুলি সরাসরি আপনার কাছে সংগ্রহ করা হয়।",
  "Required questions — answer all of them": "প্রয়োজনীয় প্রশ্ন - তাদের সব উত্তর",
  "Yes": "হ্যাঁ",
  "No": "না",
  "documents will be added to your checklist.": "নথিগুলি আপনার চেকলিস্টে যোগ করা হবে।",
  "These are separate applications, not a package requiring every form. FS-240 is the issued certificate, not an application. Complete a separate file for each child and give each parent's details separately. Scans do not replace originals or certified copies at the interview. Follow the embassy's checklist and signature instructions: do not pre-sign DS-2029 or DS-11 when a witnessed signature is required; DS-3053 requires notarization and consent is generally submitted within 90 days. A U.S. address or tax return alone does not prove physical presence. Related-form intake uses the shared questionnaire you provided, not a substitute for official form instructions.": "এগুলি পৃথক অ্যাপ্লিকেশন, প্রতিটি ফর্মের জন্য একটি প্যাকেজ নয়৷ FS-240 হল জারি করা শংসাপত্র, একটি আবেদন নয়। প্রতিটি সন্তানের জন্য একটি পৃথক ফাইল সম্পূর্ণ করুন এবং প্রতিটি পিতামাতার বিবরণ আলাদাভাবে দিন। স্ক্যানগুলি ইন্টারভিউতে আসল বা প্রত্যয়িত কপি প্রতিস্থাপন করে না। দূতাবাসের চেকলিস্ট এবং স্বাক্ষর নির্দেশাবলী অনুসরণ করুন: প্রত্যক্ষ স্বাক্ষরের প্রয়োজন হলে DS-2029 বা DS-11-এ আগে থেকে স্বাক্ষর করবেন না; DS-3053 নোটারাইজেশন প্রয়োজন এবং সম্মতি সাধারণত 90 দিনের মধ্যে জমা দেওয়া হয়। শুধুমাত্র একটি মার্কিন ঠিকানা বা ট্যাক্স রিটার্ন শারীরিক উপস্থিতি প্রমাণ করে না। সম্পর্কিত-ফর্ম গ্রহণ আপনার দেওয়া শেয়ার করা প্রশ্নাবলী ব্যবহার করে, অফিসিয়াল ফর্ম নির্দেশাবলীর বিকল্প নয়।",
  "Full name (as your electronic signature)": "পুরো নাম (আপনার ইলেকট্রনিক স্বাক্ষর হিসাবে)",
  "I have read this declaration and I sign it and agree to all of it.": "আমি এই ঘোষণাটি পড়েছি এবং আমি এতে সই করেছি এবং এর সব কিছুর সাথে সম্মত।",
  "The NVC stage can only start after the USCIS petition stage is completed and approved (with us or elsewhere). Open a USCIS file first.": "NVC পর্যায় শুধুমাত্র USCIS পিটিশন পর্যায় সম্পূর্ণ এবং অনুমোদিত হওয়ার পরেই শুরু হতে পারে (আমাদের সাথে বা অন্য কোথাও)। প্রথমে একটি USCIS ফাইল খুলুন।",
  "The embassy stage can only start after the USCIS petition is approved and the NVC stage is complete (with us or elsewhere). Open a USCIS or NVC file first.": "দূতাবাসের পর্যায়টি শুধুমাত্র USCIS পিটিশন অনুমোদিত হওয়ার পরে এবং NVC পর্যায় সম্পূর্ণ হওয়ার পরেই শুরু হতে পারে (আমাদের সাথে বা অন্য কোথাও)। প্রথমে একটি USCIS বা NVC ফাইল খুলুন।",
