  "Please answer every question": "Tanpri reponn chak kesyon",
  "You must sign the declaration": "Ou dwe siyen deklarasyon an",
  "+ Open a new documentation file": "+ Louvri yon nouvo dosye dokiman",
  "Open a documentation file": "Louvri yon dosye dokiman",
  "Service": "Sèvis",
  "Choose the service": "Chwazi sèvis la",
  "Form you selected (optional)": "Fòm ou chwazi (si ou vle)",
  "Choose a service first to see its forms": "Chwazi yon sèvis an premye pou wè fòm li yo",
  "No forms are linked to this service — its documents are collected with you directly.": "Pa gen fòm ki lye ak sèvis sa a — dokiman li yo kolekte avèk ou dirèkteman.",
  "Required questions — answer all of them": "Kesyon obligatwa yo - reponn yo tout",
  "Yes": "Wi",
  "No": "Non",
  "documents will be added to your checklist.": "dokiman yo pral ajoute nan lis verifikasyon ou a.",
  "These are separate applications, not a package requiring every form. FS-240 is the issued certificate, not an application. Complete a separate file for each child and give each parent's details separately. Scans do not replace originals or certified copies at the interview. Follow the embassy's checklist and signature instructions: do not pre-sign DS-2029 or DS-11 when a witnessed signature is required; DS-3053 requires notarization and consent is generally submitted within 90 days. A U.S. address or tax return alone does not prove physical presence. Related-form intake uses the shared questionnaire you provided, not a substitute for official form instructions.": "Sa yo se aplikasyon separe, pa yon pake ki egzije chak fòm. FS-240 se sètifika ki bay la, se pa yon aplikasyon. Ranpli yon dosye separe pou chak timoun epi bay detay chak paran yo separeman. Scans pa ranplase orijinal oswa kopi sètifye nan entèvyou a. Swiv lis verifikasyon anbasad la ak enstriksyon siyati yo: pa siyen DS-2029 oswa DS-11 davans lè yo mande yon siyati temwen; DS-3053 mande pou notarye epi konsantman an jeneral soumèt nan 90 jou. Yon adrès ameriken oswa yon deklarasyon taks poukont li pa pwouve prezans fizik. Fòm ki gen rapò ak admisyon itilize kesyonè pataje ou te bay la, pa yon ranplasan pou enstriksyon fòm ofisyèl yo.",
  "Full name (as your electronic signature)": "Non konplè (tankou siyati elektwonik ou)",
  "I have read this declaration and I sign it and agree to all of it.": "Mwen te li deklarasyon sa a epi mwen siyen li epi mwen dakò ak tout li.",
  "The NVC stage can only start after the USCIS petition stage is completed and approved (with us or elsewhere). Open a USCIS file first.": "Etap NVC a ka kòmanse sèlman apre etap petisyon USCIS la fini ak apwouve (avèk nou oswa yon lòt kote). Louvri yon dosye USCIS an premye.",
  "The embassy stage can only start after the USCIS petition is approved and the NVC stage is complete (with us or elsewhere). Open a USCIS or NVC file first.": "Etap anbasad la ka kòmanse sèlman apre yo fin apwouve petisyon USCIS la epi apre etap NVC la fini (avèk nou oswa yon lòt kote). Louvri yon dosye USCIS oswa NVC an premye.",
  "Open file": "Louvri dosye",
