  "I alone am fully responsible for the accuracy and authenticity of this information and documents and for any consequence arising from them. MIGRAFILE bears no responsibility for them.": "Μόνο εγώ είμαι πλήρως υπεύθυνος για την ακρίβεια και την αυθεντικότητα αυτών των πληροφοριών και εγγράφων και για κάθε συνέπεια που προκύπτει από αυτά. Η MIGRAFILE δεν φέρει καμία ευθύνη για αυτά.",
  "I understand MIGRAFILE provides documentation organization services only — not legal advice — and is not affiliated with USCIS, NVC or the U.S. Department of State, and does not guarantee any outcome.": "Κατανοώ ότι το MIGRAFILE παρέχει υπηρεσίες οργάνωσης τεκμηρίωσης μόνο —όχι νομικές συμβουλές— και δεν συνδέεται με το USCIS, το NVC ή το Υπουργείο Εξωτερικών των ΗΠΑ και δεν εγγυάται κανένα αποτέλεσμα.",
  "Petitioner proof of U.S. citizenship or green card": "Απόδειξη υπηκοότητας ή πράσινης κάρτας από τον αναφέροντα",
  "Beneficiary passport (bio page)": "Διαβατήριο δικαιούχου (βιογραφική σελίδα)",
