  "Marriage certificate (if spouse)": "Ληξιαρχική πράξη γάμου (εάν είναι σύζυγος)",
  "Divorce or death certificates for any prior marriages": "Πιστοποιητικά διαζυγίου ή θανάτου για τυχόν προηγούμενους γάμους",
  "Evidence of the relationship (photos, correspondence)": "Αποδεικτικά στοιχεία της σχέσης (φωτογραφίες, αλληλογραφία)",
  "Passport-style photos": "Φωτογραφίες σε στυλ διαβατηρίου",
