  "Organized.": "Οργανωμένος.",
  "Professional documentation and case-management support. We organize the process — you stay in control.": "Επαγγελματική τεκμηρίωση και υποστήριξη διαχείρισης υποθέσεων. Οργανώνουμε τη διαδικασία — εσείς διατηρείτε τον έλεγχο.",
  "Start My Case": "Ξεκινήστε την υπόθεση μου",
