  "From intake to an approved package": "Από τη λήψη σε ένα εγκεκριμένο πακέτο",
  "Legal Disclaimer": "Νομική Αποποίηση Ευθύνης",
  "MIGRAFILE is a documentation assistance service. We are not a law firm, are not affiliated with USCIS or any government agency, and do not provide legal advice or representation. Our work is limited to preparing and organizing documents.": "Το MIGRAFILE είναι μια υπηρεσία υποστήριξης τεκμηρίωσης. Δεν είμαστε δικηγορική εταιρεία, δεν είμαστε συνδεδεμένοι με το USCIS ή οποιαδήποτε κυβερνητική υπηρεσία και δεν παρέχουμε νομικές συμβουλές ή εκπροσώπηση. Η εργασία μας περιορίζεται στην προετοιμασία και την οργάνωση εγγράφων.",
  "Ready to get your file organized?": "Είστε έτοιμοι να οργανώσετε το αρχείο σας;",
