  "MIGRAFILE Knowledge": "MIGRAFILE Γνώση",
  "U.S. Immigration Knowledge Hub": "Κόμβος Γνώσης Μετανάστευσης ΗΠΑ",
  "General educational information, each article linked to its official source.": "Γενικές εκπαιδευτικές πληροφορίες, κάθε άρθρο συνδέεται με την επίσημη πηγή του.",
  "Educational content is not legal advice and does not tell you what to file.": "Το εκπαιδευτικό περιεχόμενο δεν είναι νομική συμβουλή και δεν σας λέει τι να υποβάλετε.",
  "Articles in source review": "Άρθρα σε ανασκόπηση πηγής",
  "Legal": "Νομική",
  "Important legal notice": "Σημαντική νομική ειδοποίηση",
  "Not a law firm": "Όχι δικηγορικό γραφείο",
  "MIGRAFILE is not a law firm, not a U.S. government agency, and is not affiliated with USCIS or the U.S. Department of State. We do not provide legal advice or representation.": "Η MIGRAFILE δεν είναι δικηγορική εταιρεία, ούτε κυβερνητική υπηρεσία των ΗΠΑ και δεν συνδέεται με το USCIS ή το Υπουργείο Εξωτερικών των ΗΠΑ. Δεν παρέχουμε νομικές συμβουλές ή εκπροσώπηση.",
  "Client-directed document preparation": "Προετοιμασία εγγράφων κατευθυνόμενη από τον πελάτη",
  "You select the process and provide the answers. You are responsible for reviewing and approving everything submitted.": "Εσείς επιλέγετε τη διαδικασία και δίνετε τις απαντήσεις. Είστε υπεύθυνοι για τον έλεγχο και την έγκριση όλων των υποβληθέντων.",
  "Terms of service": "Όροι παροχής υπηρεσιών",
