  "We can't select a process for you. Review neutral official resources, or seek help from qualified U.S. immigration counsel.": "Nie możemy wybrać procesu za Ciebie. Przejrzyj neutralne oficjalne źródła lub zwróć się o pomoc do wykwalifikowanego doradcy ds. imigracji w USA.",
