  "Always confirm the current edition and fee on the official agency website before filing.": "Przed złożeniem wniosku zawsze potwierdzaj aktualne wydanie i opłatę na oficjalnej stronie internetowej agencji.",
  "Search forms (e.g. I-130)": "Formularze wyszukiwania (np. I-130)",
  "A clear process you control": "Przejrzysty proces, nad którym masz kontrolę",
  "1. Intake": "1. Spożycie",
  "You choose the service and provide your facts and documents.": "Wybierasz usługę i podajesz fakty oraz dokumenty.",
  "2. Scope review — GREEN / YELLOW / RED": "2. Przegląd zakresu — ZIELONY / ŻÓŁTY / CZERWONY",
  "We confirm the request is administrative and within our scope.": "Potwierdzamy, że żądanie ma charakter administracyjny i mieści się w naszym zakresie.",
  "3. Document specialist": "3. Specjalista ds. dokumentów",
  "Your file is organized, translated and a missing-documents report is issued.": "Twoje akta zostaną uporządkowane, przetłumaczone i wystawiony zostanie raport o brakujących dokumentach.",
  "4. Independent quality control": "4. Niezależna kontrola jakości",
