  "5. Your review & authorization": "5. Twoja recenzja i autoryzacja",
  "You review every answer, approve and sign. Nothing is submitted without you.": "Sprawdzasz każdą odpowiedź, zatwierdzasz i podpisujesz. Nic nie zostanie złożone bez Ciebie.",
  "Files completed": "Pliki ukończone",
