  "Files in progress": "Pliki w toku",
  "Years of experience": "Lata doświadczeń",
  "Tell us what help you need": "Powiedz nam jakiej pomocy potrzebujesz",
  "Translation, organizing a file, data entry for a form you selected, or tracking.": "Tłumaczenie, porządkowanie pliku, wprowadzanie danych do wybranego formularza lub śledzenie.",
  "Scope review": "Przegląd zakresu",
  "Every case is checked against our GREEN / YELLOW / RED scope system before work begins.": "Przed rozpoczęciem pracy każdy przypadek jest sprawdzany pod kątem naszego systemu zakresów ZIELONY/ŻÓŁTY/CZERWONY.",
  "Document specialist & QC": "Specjalista ds. dokumentów i kontroli jakości",
  "A specialist organizes your file; an independent reviewer checks it.": "Specjalista porządkuje Twoje pliki; sprawdza to niezależny recenzent.",
  "You review and approve": "Przeglądasz i zatwierdzasz",
  "Nothing is submitted without your explicit approval and signature.": "Nic nie jest przesyłane bez Twojej wyraźnej zgody i podpisu.",
