  "Your immigration file.": "Twoje akta imigracyjne.",
  "Organized.": "Zorganizowany.",
  "Professional documentation and case-management support. We organize the process — you stay in control.": "Profesjonalna dokumentacja i wsparcie w zarządzaniu sprawami. Organizujemy proces – Ty masz kontrolę.",
  "Start My Case": "Rozpocznij moją sprawę",
  "Browse services": "Przeglądaj usługi",
