  "Documentation support, clearly scoped": "Wsparcie dokumentacji, jasno określone",
  "From intake to an approved package": "Od przyjęcia do zatwierdzonego opakowania",
  "Legal Disclaimer": "Zastrzeżenie prawne",
  "MIGRAFILE is a documentation assistance service. We are not a law firm, are not affiliated with USCIS or any government agency, and do not provide legal advice or representation. Our work is limited to preparing and organizing documents.": "MIGRAFILE to usługa pomocy w dokumentacji. Nie jesteśmy kancelarią prawną, nie jesteśmy powiązani z USCIS ani żadną agencją rządową i nie zapewniamy porad prawnych ani reprezentacji. Nasza praca ogranicza się do przygotowania i uporządkowania dokumentów.",
  "Ready to get your file organized?": "Chcesz uporządkować swoje pliki?",
  "Open a secure case, upload your documents, and follow every stage.": "Otwórz bezpieczną skrzynkę, prześlij dokumenty i śledź każdy etap.",
  "MIGRAFILE Knowledge": "Wiedza MIGRAFILE",
  "U.S. Immigration Knowledge Hub": "Centrum wiedzy o imigracji w USA",
  "General educational information, each article linked to its official source.": "Ogólne informacje edukacyjne, każdy artykuł powiązany z oficjalnym źródłem.",
  "Educational content is not legal advice and does not tell you what to file.": "Treści edukacyjne nie stanowią porady prawnej i nie zawierają wskazówek, co należy złożyć.",
  "Articles in source review": "Artykuły w przeglądzie źródłowym",
  "Legal": "Legalne",
  "Important legal notice": "Ważna informacja prawna",
  "Not a law firm": "Nie kancelaria prawnicza",
  "MIGRAFILE is not a law firm, not a U.S. government agency, and is not affiliated with USCIS or the U.S. Department of State. We do not provide legal advice or representation.": "MIGRAFILE nie jest firmą prawniczą ani agencją rządową USA i nie jest powiązana z USCIS ani Departamentem Stanu USA. Nie zapewniamy porad prawnych ani reprezentacji.",
  "Client-directed document preparation": "Przygotowanie dokumentów pod kątem klienta",
  "You select the process and provide the answers. You are responsible for reviewing and approving everything submitted.": "Wybierasz proces i podajesz odpowiedzi. Jesteś odpowiedzialny za sprawdzenie i zatwierdzenie wszystkich przesłanych materiałów.",
  "Terms of service": "Warunki usługi",
  "Full terms, refund policy and client authorization will be published before payments are enabled.": "Pełne warunki, zasady zwrotów i autoryzacja klienta zostaną opublikowane przed włączeniem płatności.",
  "Scope": "Zakres",
  "When a matter needs legal judgment, we pause and refer you.": "Gdy sprawa wymaga oceny prawnej, wstrzymujemy się i odsyłamy Cię.",
  "We do not": "Nie",
  "Give legal advice or recommend a visa, form or legal route": "Udziel porady prawnej lub zarekomenduj wizę, formularz lub drogę prawną",
  "Determine eligibility, citizenship or sponsor eligibility": "Określ uprawnienia, obywatelstwo lub uprawnienia sponsora",
  "Predict approval chances": "Przewiduj szanse na zatwierdzenie",
