  "Represent you before USCIS, the State Department or immigration court": "Reprezentuj Cię przed USCIS, Departamentem Stanu lub sądem imigracyjnym",
  "What happens instead": "Co się dzieje zamiast tego",
  "Affected work is placed on hold (RED) and you are directed to independently qualified U.S. counsel.": "Prace, których to dotyczy, zostają wstrzymane (RED) i zostaniesz skierowany do niezależnie wykwalifikowanego prawnika w USA.",
  "Set a new password": "Ustaw nowe hasło",
