  "Go straight to the source. These sites are operated by the U.S. government, not by MIGRAFILE.": "Idź prosto do źródła. Strony te są obsługiwane przez rząd Stanów Zjednoczonych, a nie przez MIGRAFILE.",
  "Government websites end in .gov. Be cautious of sites that imitate official agencies.": "Witryny rządowe mają końcówkę .gov. Zachowaj ostrożność w przypadku witryn imitujących oficjalne agencje.",
  "Security": "Bezpieczeństwo",
  "Principles": "Zasady",
  "Private documents are never publicly accessible": "Dokumenty prywatne nigdy nie są publicznie dostępne",
  "Case tracking requires authentication — never by case number alone": "Śledzenie spraw wymaga uwierzytelnienia — nigdy na podstawie samego numeru sprawy",
