  "NVC & Visa Tools": "Narzędzia NVC i wizowe",
  "Tools for the consular stage: CEAC, NVC timeframes, visa availability and scheduling.": "Narzędzia na etapie konsularnym: ramy czasowe CEAC, NVC, dostępność wiz i harmonogram.",
