  "IV Scheduling Status Tool": "IV Narzędzie stanu planowania",
  "See which interview dates each embassy is currently scheduling. It does not give you a personal appointment.": "Sprawdź, jakie daty rozmów kwalifikacyjnych są obecnie zaplanowane w poszczególnych ambasadach. Nie zapewnia osobistego spotkania.",
  "Documents & Embassies": "Dokumenty i ambasady",
  "Which document is accepted, who issues it, and your embassy's interview instructions.": "Który dokument jest akceptowany, kto go wystawia i instrukcje dotyczące rozmowy kwalifikacyjnej w ambasadzie.",
  "Reciprocity & Civil Documents by Country": "Wzajemność i dokumenty cywilne według kraju",
