  "U.S. Embassies Directory": "Katalog ambasad USA",
  "Find the official website of the embassy handling your case.": "Znajdź oficjalną stronę ambasady zajmującej się Twoją sprawą.",
  "U.S. Embassy Cairo — Immigrant Visas": "Ambasada USA w Kairze — Wizy imigracyjne",
  "Cairo interview documents, medical exam, registration and local instructions.": "Dokumenty do rozmowy kwalifikacyjnej w Kairze, badanie lekarskie, rejestracja i lokalne instrukcje.",
  "Financial Evidence Assistant": "Asystent ds. dowodów finansowych",
  "Understand which financial documents fit the sponsor's circumstances.": "Dowiedz się, które dokumenty finansowe odpowiadają sytuacji sponsora.",
  "IRS — Tax Records for the Sponsor": "IRS — dokumentacja podatkowa sponsora",
  "Get tax transcripts free from the IRS for the affidavit of support. The transcript belongs to the sponsor or joint sponsor — not the visa applicant.": "Uzyskaj bezpłatne transkrypcje podatkowe z IRS w celu uzyskania oświadczenia o wsparciu. Transkrypcja należy do sponsora lub współsponsora, a nie osoby ubiegającej się o wizę.",
  "IRS — Get Transcript": "IRS — pobierz transkrypcję",
  "Get your tax record online or order it by mail — free of charge.": "Uzyskaj zeznanie podatkowe online lub zamów je pocztą – bezpłatnie.",
  "Start with Tax Return Transcript": "Zacznij od transkrypcji zeznania podatkowego",
  "IRS Online Account": "Konto internetowe IRS",
  "Sign in to your personal IRS account and access your records. MIGRAFILE never asks for your IRS password or verification codes.": "Zaloguj się na swoje osobiste konto IRS i uzyskaj dostęp do swoich danych. MIGRAFILE nigdy nie prosi o hasło IRS ani kody weryfikacyjne.",
  "Get Transcript — FAQs": "Pobierz transkrypcję — często zadawane pytania",
  "Solve availability problems or order the record another way.": "Rozwiąż problemy z dostępnością lub zamów płytę w inny sposób.",
  "Form 4506-T": "Formularz 4506-T",
  "Request records by mail when not using the online account.": "Jeśli nie korzystasz z konta online, poproś o dokumentację pocztą.",
  "Other Official Sources": "Inne oficjalne źródła",
  "Trusted government sources that serve your case beyond USCIS and NVC.": "Zaufane źródła rządowe, które obsługują Twoją sprawę poza USCIS i NVC.",
  "CBP I-94": "CBP I-94",
  "Retrieve your electronic entry record and available travel history. It is a reference tool, not a complete legal record.": "Pobierz swój elektroniczny rekord wjazdu i dostępną historię podróży. Jest to narzędzie referencyjne, a nie pełny zapis prawny.",
  "USCIS — Avoid Scams": "USCIS — unikaj oszustw",
  "Learn to recognize fraud and find authorized legal help.": "Naucz się rozpoznawać oszustwa i znajdź autoryzowaną pomoc prawną.",
  "SAVE CaseCheck": "ZAPISZ Sprawę Sprawdź",
  "Track a pending immigration-status verification request, when one exists.": "Śledź oczekującą prośbę o weryfikację statusu imigracyjnego, jeśli taka istnieje.",
  "Document & Photo Toolkit": "Zestaw narzędzi do dokumentów i zdjęć",
  "Practical utilities to prepare files before uploading. Some features need an account or subscription.": "Praktyczne narzędzia do przygotowania plików przed przesłaniem. Niektóre funkcje wymagają konta lub subskrypcji.",
  "Merge & Compress PDF — iLovePDF": "Scal i kompresuj pliki PDF — iLovePDF",
  "Merge, split, compress and convert files. Review text and stamp clarity after compressing.": "Łącz, dziel, kompresuj i konwertuj pliki. Sprawdź przejrzystość tekstu i stempla po skompresowaniu.",
  "PDF Tools — Smallpdf": "Narzędzia PDF — Smallpdf",
  "Compress, convert, edit and sign PDFs.": "Kompresuj, konwertuj, edytuj i podpisuj pliki PDF.",
  "PDF Tools — Adobe Acrobat Online": "Narzędzia PDF — Adobe Acrobat Online",
  "Organize, convert and compress PDF files online.": "Porządkuj, konwertuj i kompresuj pliki PDF online.",
  "PDF24 Tools": "Narzędzia PDF24",
  "Free file tools, with a desktop option that processes files locally without uploading them.": "Darmowe narzędzia do plików z opcją komputerową, która przetwarza pliki lokalnie bez ich przesyłania.",
  "E-Signature — DocuSign": "Podpis elektroniczny — DocuSign",
  "Send MIGRAFILE contracts and service consents for signature. Check each government form's instructions first — an e-signature is not automatically accepted by USCIS.": "Przesyłaj umowy MIGRAFILE i zgody na świadczenie usług do podpisu. Najpierw sprawdź instrukcje zawarte w każdym formularzu rządowym — podpis elektroniczny nie jest automatycznie akceptowany przez USCIS.",
  "E-Signature — Adobe & Smallpdf": "Podpis elektroniczny — Adobe i Smallpdf",
  "Fill PDFs and add signatures online.": "Wypełniaj pliki PDF i dodawaj podpisy online.",
