  "Change width and height in pixels or percentage. Keep the aspect ratio so faces or documents don't stretch.": "Zmień szerokość i wysokość w pikselach lub procentach. Zachowaj proporcje, aby twarze lub dokumenty się nie rozciągały.",
  "Compress & Crop — iLoveIMG": "Kompresuj i kadruj — iLoveIMG",
  "Reduce file size in KB/MB or crop a photo. Compress changes size; crop changes framing.": "Zmniejsz rozmiar pliku w KB/MB lub przytnij zdjęcie. Kompresja zmienia rozmiar; kadrowanie zmian kadrowania.",
  "iLoveIMG in Arabic": "iLoveIMG w języku arabskim",
  "Access the tools with an Arabic interface.": "Uzyskaj dostęp do narzędzi z interfejsem arabskim.",
  "Visa Photos — Official Requirements": "Zdjęcia wizowe — oficjalne wymagania",
  "Start with the U.S. Department of State's digital photo requirements, including the official photo tool. Resizing alone does not guarantee acceptance.": "Zacznij od wymagań Departamentu Stanu USA dotyczących zdjęć cyfrowych, w tym oficjalnego narzędzia do zdjęć. Sama zmiana rozmiaru nie gwarantuje akceptacji.",
  "MIGRAFILE Tools": "Narzędzia MIGRAFILE",
  "Official tools & sources": "Oficjalne narzędzia i źródła",
  "Direct links to the official tools for each stage of your case — USCIS, NVC, the embassy, IRS — plus utilities to prepare your documents. MIGRAFILE links to these sources only; it does not operate them.": "Bezpośrednie linki do oficjalnych narzędzi na każdym etapie Twojej sprawy — USCIS, NVC, ambasady, IRS — oraz narzędzi do przygotowywania dokumentów. MIGRAFILE odsyła wyłącznie do tych źródeł; ich nie obsługuje.",
  "These are official external government sources. MIGRAFILE is an independent platform and is not affiliated with USCIS or the U.S. Department of State. Links last reviewed: October 2026.": "Są to oficjalne zewnętrzne źródła rządowe. MIGRAFILE jest niezależną platformą i nie jest powiązana z USCIS ani Departamentem Stanu USA. Linki ostatnio sprawdzane: październik 2026 r.",
  "Open official source": "Otwórz oficjalne źródło",
  "Track my case": "Śledź moją sprawę",
  "Secure sign-in is required to view any case information. For your protection, cases cannot be looked up by case number alone.": "Aby wyświetlić informacje o sprawie, wymagane jest bezpieczne logowanie. Dla Twojego bezpieczeństwa spraw nie można wyszukiwać wyłącznie według numeru sprawy.",
