  "No forms are linked to this service — its documents are collected with you directly.": "Żadne formularze nie są powiązane z tą usługą – jej dokumenty są odbierane bezpośrednio u Ciebie.",
  "Required questions — answer all of them": "Pytania wymagane — odpowiedz na wszystkie",
  "Yes": "Tak",
  "No": "Nie",
  "documents will be added to your checklist.": "dokumenty zostaną dodane do Twojej listy kontrolnej.",
  "These are separate applications, not a package requiring every form. FS-240 is the issued certificate, not an application. Complete a separate file for each child and give each parent's details separately. Scans do not replace originals or certified copies at the interview. Follow the embassy's checklist and signature instructions: do not pre-sign DS-2029 or DS-11 when a witnessed signature is required; DS-3053 requires notarization and consent is generally submitted within 90 days. A U.S. address or tax return alone does not prove physical presence. Related-form intake uses the shared questionnaire you provided, not a substitute for official form instructions.": "Są to osobne aplikacje, a nie pakiet wymagający każdej formy. FS-240 to wydawany certyfikat, a nie aplikacja. Wypełnij oddzielny plik dla każdego dziecka i osobno podaj dane każdego rodzica. Skany nie zastępują oryginałów ani poświadczonych kopii podczas rozmowy kwalifikacyjnej. Postępuj zgodnie z listą kontrolną ambasady i instrukcjami dotyczącymi składania podpisu: nie podpisuj wcześniej DS-2029 ani DS-11, gdy wymagany jest podpis poświadczony; DS-3053 wymaga poświadczenia notarialnego, a zgoda jest zazwyczaj składana w ciągu 90 dni. Sam adres w USA lub zeznanie podatkowe nie stanowią dowodu fizycznej obecności. Przyjmowanie powiązanych formularzy korzysta z udostępnionego kwestionariusza, który podałeś i nie zastępuje oficjalnych instrukcji formularza.",
  "Full name (as your electronic signature)": "Imię i nazwisko (jako Twój podpis elektroniczny)",
  "I have read this declaration and I sign it and agree to all of it.": "Przeczytałem niniejszą deklarację, podpisuję ją i zgadzam się ze wszystkim.",
  "The NVC stage can only start after the USCIS petition stage is completed and approved (with us or elsewhere). Open a USCIS file first.": "Etap NVC można rozpocząć dopiero po zakończeniu i zatwierdzeniu etapu petycji USCIS (u nas lub gdzie indziej). Najpierw otwórz plik USCIS.",
  "The embassy stage can only start after the USCIS petition is approved and the NVC stage is complete (with us or elsewhere). Open a USCIS or NVC file first.": "Etap ambasady może rozpocząć się dopiero po zatwierdzeniu petycji USCIS i zakończeniu etapu NVC (u nas lub gdzie indziej). Najpierw otwórz plik USCIS lub NVC.",
  "Open file": "Otwórz plik",
