  "I personally selected this service and the form(s) in this file, of my own free choice. MIGRAFILE did not choose, recommend or advise on any visa, form or immigration route for me.": "Я особисто вибрав цю послугу та форму (форми) у цьому файлі за власним вибором. MIGRAFILE не вибирав, не рекомендував і не радив для мене жодну візу, форму чи імміграційний маршрут.",
  "All answers I provided and every document I upload to this file were provided by me personally.": "Усі надані мною відповіді та всі документи, які я завантажую до цього файлу, надані мною особисто.",
  "I declare that all information and documents are true, accurate, complete and genuine, and not altered or forged.": "Я заявляю, що вся інформація та документи є правдивими, точними, повними та справжніми, а не зміненими чи підробленими.",
  "I alone am fully responsible for the accuracy and authenticity of this information and documents and for any consequence arising from them. MIGRAFILE bears no responsibility for them.": "Лише я несу повну відповідальність за точність і достовірність цієї інформації та документів, а також за будь-які наслідки, що з них випливають. MIGRAFILE не несе за них відповідальності.",
  "I understand MIGRAFILE provides documentation organization services only — not legal advice — and is not affiliated with USCIS, NVC or the U.S. Department of State, and does not guarantee any outcome.": "Я розумію, що MIGRAFILE надає лише послуги з організації документації, а не юридичні консультації, і не пов’язана з USCIS, NVC або Державним департаментом США, і не гарантує жодних результатів.",
  "Petitioner proof of U.S. citizenship or green card": "Підтвердження громадянства США або зеленої карти позивача",
