  "No": "немає",
  "documents will be added to your checklist.": "документів буде додано до вашого контрольного списку.",
  "These are separate applications, not a package requiring every form. FS-240 is the issued certificate, not an application. Complete a separate file for each child and give each parent's details separately. Scans do not replace originals or certified copies at the interview. Follow the embassy's checklist and signature instructions: do not pre-sign DS-2029 or DS-11 when a witnessed signature is required; DS-3053 requires notarization and consent is generally submitted within 90 days. A U.S. address or tax return alone does not prove physical presence. Related-form intake uses the shared questionnaire you provided, not a substitute for official form instructions.": "Це окремі програми, а не пакет, який потребує кожної форми. FS-240 - це виданий сертифікат, а не заява. Заповніть окремий файл для кожної дитини та надайте дані кожного з батьків окремо. Скановані копії не замінюють оригінали чи завірені копії на співбесіді. Дотримуйтеся контрольного списку посольства та інструкцій щодо підпису: не підписуйте попередньо DS-2029 або DS-11, якщо потрібен підпис завіреного; DS-3053 вимагає нотаріального засвідчення, і згода зазвичай подається протягом 90 днів. Сама по собі адреса чи податкова декларація в США не є доказом фізичної присутності. Для отримання пов’язаної форми використовується спільна анкета, яку ви надали, а не заміна офіційних інструкцій щодо форми.",
  "Full name (as your electronic signature)": "ПІБ (як ваш електронний підпис)",
  "I have read this declaration and I sign it and agree to all of it.": "Я прочитав цю декларацію, підписав її та згоден з усім.",
  "The NVC stage can only start after the USCIS petition stage is completed and approved (with us or elsewhere). Open a USCIS file first.": "Етап NVC може розпочатися лише після завершення та схвалення етапу подання петиції USCIS (нами чи деінде). Спочатку відкрийте файл USCIS.",
  "The embassy stage can only start after the USCIS petition is approved and the NVC stage is complete (with us or elsewhere). Open a USCIS or NVC file first.": "Етап посольства може розпочатися лише після схвалення петиції USCIS і завершення етапу NVC (у нас чи деінде). Спочатку відкрийте файл USCIS або NVC.",
