  "Visa Bulletin": "Iwe itẹjade Visa",
  "Follow visa availability for categories subject to numerical limits.": "Tẹle wiwa fisa fun awọn ẹka koko ọrọ si awọn opin nọmba.",
  "IV Scheduling Status Tool": "IV Iṣeto Ipo Ọpa",
  "See which interview dates each embassy is currently scheduling. It does not give you a personal appointment.": "Wo iru awọn ọjọ ifọrọwanilẹnuwo wo ni ile-iṣẹ ikọlu kọọkan n ṣe eto lọwọlọwọ. Ko fun ọ ni ipinnu lati pade ti ara ẹni.",
  "Documents & Embassies": "Awọn iwe aṣẹ & Embassies",
  "Which document is accepted, who issues it, and your embassy's interview instructions.": "Iwe wo ni o gba, tani o gbejade, ati awọn itọnisọna ifọrọwanilẹnuwo ti ile-iṣẹ aṣoju aṣoju rẹ.",
  "Reciprocity & Civil Documents by Country": "Reciprocity & Awọn iwe aṣẹ ilu nipasẹ Orilẹ-ede",
  "Which document is accepted and who issues it in each country.": "Iwe wo ni o gba ati tani o fun ni orilẹ-ede kọọkan.",
  "U.S. Embassies Directory": "U.S. Embassies Directory",
  "Find the official website of the embassy handling your case.": "Wa oju opo wẹẹbu osise ti ile-iṣẹ ijọba ti n ṣakoso ọran rẹ.",
  "U.S. Embassy Cairo — Immigrant Visas": "Ile-iṣẹ ọlọpa AMẸRIKA Cairo - Awọn iwe iwọlu aṣikiri",
  "Cairo interview documents, medical exam, registration and local instructions.": "Awọn iwe ifọrọwanilẹnuwo Cairo, idanwo iṣoogun, iforukọsilẹ ati awọn ilana agbegbe.",
  "Financial Evidence Assistant": "Oluranlọwọ Ẹri Owo",
  "Understand which financial documents fit the sponsor's circumstances.": "Loye iru awọn iwe aṣẹ inawo ni ibamu pẹlu awọn ipo onigbowo naa.",
  "IRS — Tax Records for the Sponsor": "IRS - Awọn igbasilẹ owo-ori fun Onigbowo naa",
  "Get tax transcripts free from the IRS for the affidavit of support. The transcript belongs to the sponsor or joint sponsor — not the visa applicant.": "Gba awọn iwe afọwọkọ owo-ori ọfẹ lati IRS fun ijẹrisi atilẹyin. Tiransikiripiti naa jẹ ti onigbowo tabi onigbowo apapọ - kii ṣe olubẹwẹ fisa.",
  "IRS — Get Transcript": "IRS - Gba Tiransikiripiti",
  "Get your tax record online or order it by mail — free of charge.": "Gba igbasilẹ owo-ori rẹ lori ayelujara tabi paṣẹ nipasẹ meeli — laisi idiyele.",
  "Start with Tax Return Transcript": "Bẹrẹ pẹlu Tiransikiripiti Pada Tax",
  "IRS Online Account": "IRS Online Account",
  "Sign in to your personal IRS account and access your records. MIGRAFILE never asks for your IRS password or verification codes.": "Wọle si akọọlẹ IRS ti ara ẹni ki o wọle si awọn igbasilẹ rẹ. MIGRAFILE ko beere fun ọrọ igbaniwọle IRS rẹ tabi awọn koodu ijẹrisi.",
  "Get Transcript — FAQs": "Gba Tiransikiripiti - Awọn ibeere FAQ",
  "Solve availability problems or order the record another way.": "Yanju awọn iṣoro wiwa tabi paṣẹ igbasilẹ ni ọna miiran.",
  "Form 4506-T": "Fọọmu 4506-T",
  "Request records by mail when not using the online account.": "Beere awọn igbasilẹ nipasẹ meeli nigbati o ko lo akọọlẹ ori ayelujara.",
  "Other Official Sources": "Miiran Osise orisun",
  "Trusted government sources that serve your case beyond USCIS and NVC.": "Awọn orisun ijọba ti o gbẹkẹle ti o ṣe iranṣẹ ọran rẹ kọja USCIS ati NVC.",
  "CBP I-94": "CBP I-94",
  "Retrieve your electronic entry record and available travel history. It is a reference tool, not a complete legal record.": "Gba igbasilẹ titẹsi itanna rẹ pada ati itan irin-ajo ti o wa. O jẹ ohun elo itọkasi, kii ṣe igbasilẹ ofin pipe.",
  "USCIS — Avoid Scams": "USCIS - Yago fun awọn itanjẹ",
  "Learn to recognize fraud and find authorized legal help.": "Kọ ẹkọ lati da jegudujera mọ ki o wa iranlọwọ ofin ti a fun ni aṣẹ.",
  "SAVE CaseCheck": "Fipamọ CaseCheck",
  "Track a pending immigration-status verification request, when one exists.": "Tọpinpin ibeere ijẹrisi ipo iṣiwa ti o nduro, nigbati ọkan wa.",
  "Document & Photo Toolkit": "Iwe & Ohun elo Fọto",
  "Practical utilities to prepare files before uploading. Some features need an account or subscription.": "Awọn ohun elo to wulo lati ṣeto awọn faili ṣaaju ikojọpọ. Diẹ ninu awọn ẹya nilo akọọlẹ kan tabi ṣiṣe alabapin.",
  "Merge & Compress PDF — iLovePDF": "Darapọ & Compress PDF - iLovePDF",
  "Merge, split, compress and convert files. Review text and stamp clarity after compressing.": "Dapọ, pipin, compress ati iyipada awọn faili. Atunwo ọrọ ati ontẹ wípé lẹhin funmorawon.",
  "PDF Tools — Smallpdf": "Awọn irinṣẹ PDF - Smallpdf",
  "Compress, convert, edit and sign PDFs.": "Kọ, yipada, ṣatunkọ ati fowo si awọn PDFs.",
  "PDF Tools — Adobe Acrobat Online": "Awọn irinṣẹ PDF - Adobe Acrobat Online",
  "Organize, convert and compress PDF files online.": "Ṣeto, yipada ati compress awọn faili PDF lori ayelujara.",
  "PDF24 Tools": "PDF24 Awọn irinṣẹ",
  "Free file tools, with a desktop option that processes files locally without uploading them.": "Awọn irinṣẹ faili ọfẹ, pẹlu aṣayan tabili tabili ti o ṣe ilana awọn faili ni agbegbe laisi ikojọpọ wọn.",
  "E-Signature — DocuSign": "E-Ibuwọlu - DocuSign",
  "Send MIGRAFILE contracts and service consents for signature. Check each government form's instructions first — an e-signature is not automatically accepted by USCIS.": "Firanṣẹ awọn adehun MIGRAFILE ati awọn iyọọda iṣẹ fun ibuwọlu. Ṣayẹwo awọn ilana fọọmu ijọba kọọkan ni akọkọ - Ibuwọlu e-ibuwọlu ko ni gba laifọwọyi nipasẹ USCIS.",
  "E-Signature — Adobe & Smallpdf": "Ibuwọlu E-Adobe & Smallpdf",
  "Fill PDFs and add signatures online.": "Kun PDFs ki o si fi awọn ibuwọlu lori ayelujara.",
  "Resize Images — iLoveIMG": "Ṣe atunṣe awọn aworan - iLoveIMG",
  "Change width and height in pixels or percentage. Keep the aspect ratio so faces or documents don't stretch.": "Yi iwọn ati giga pada ni awọn piksẹli tabi ipin ogorun. Jeki ipin abala naa ki awọn oju tabi awọn iwe aṣẹ ma ṣe na.",
  "Compress & Crop — iLoveIMG": "Compress & Irugbingbin - iLoveIMG",
  "Reduce file size in KB/MB or crop a photo. Compress changes size; crop changes framing.": "Din iwọn faili ku ni KB/MB tabi ge fọto kan. Compress iwọn awọn iyipada; awọn iyipada irugbin na fireemu.",
  "iLoveIMG in Arabic": "iLoveIMG ni Arabic",
  "Access the tools with an Arabic interface.": "Wọle si awọn irinṣẹ pẹlu ohun Arabic ni wiwo.",
  "Visa Photos — Official Requirements": "Visa Photos - Official ibeere",
  "Start with the U.S. Department of State's digital photo requirements, including the official photo tool. Resizing alone does not guarantee acceptance.": "Bẹrẹ pẹlu awọn ibeere fọto oni nọmba ti Ẹka ti Ipinle AMẸRIKA, pẹlu irinṣẹ fọto osise. Titunṣe iwọn nikan ko ṣe iṣeduro gbigba.",
  "MIGRAFILE Tools": "Awọn irinṣẹ MIGRAFILE",
  "Official tools & sources": "Awọn irinṣẹ osise & awọn orisun",
  "Direct links to the official tools for each stage of your case — USCIS, NVC, the embassy, IRS — plus utilities to prepare your documents. MIGRAFILE links to these sources only; it does not operate them.": "Awọn ọna asopọ taara si awọn irinṣẹ osise fun ipele kọọkan ti ọran rẹ - USCIS, NVC, ile-iṣẹ ajeji, IRS - pẹlu awọn ohun elo lati ṣeto awọn iwe aṣẹ rẹ. Awọn ọna asopọ MIGRAFILE si awọn orisun wọnyi nikan; ko ṣiṣẹ wọn.",
  "These are official external government sources. MIGRAFILE is an independent platform and is not affiliated with USCIS or the U.S. Department of State. Links last reviewed: October 2026.": "Iwọnyi jẹ awọn orisun ijọba ita gbangba. MIGRAFILE jẹ pẹpẹ ti o ni ominira ati pe ko ni ajọṣepọ pẹlu USCIS tabi Ẹka ti Ipinle AMẸRIKA. Awọn ọna asopọ ṣe atunyẹwo kẹhin: Oṣu Kẹwa Ọdun 2026.",
  "Open official source": "Ṣii orisun osise",
  "Track my case": "Tọpa ọran mi",
