  "MIGRAFILE is a documentation and case-management service. We are not a law firm, do not provide legal advice, and do not recommend visas or predict outcomes.": "MIGRAFILE jẹ iwe-ipamọ ati iṣẹ iṣakoso ọran. A kii ṣe ile-iṣẹ ofin, ko pese imọran ofin, ati pe ko ṣeduro awọn iwe iwọlu tabi asọtẹlẹ awọn abajade.",
  "You choose the form and category yourself, and you remain responsible for the accuracy of all information you provide.": "O yan fọọmu ati ẹka funrararẹ, ati pe o wa ni iduro fun deede gbogbo alaye ti o pese.",
