  "No forms are linked to this service — its documents are collected with you directly.": "Ko si awọn fọọmu ti o sopọ mọ iṣẹ yii - awọn iwe aṣẹ rẹ ni a gba pẹlu rẹ taara.",
  "Required questions — answer all of them": "Awọn ibeere ti a beere - dahun gbogbo wọn",
  "Yes": "Bẹẹni",
  "No": "Rara",
  "documents will be added to your checklist.": "awọn iwe aṣẹ yoo wa ni afikun si akojọ ayẹwo rẹ.",
  "These are separate applications, not a package requiring every form. FS-240 is the issued certificate, not an application. Complete a separate file for each child and give each parent's details separately. Scans do not replace originals or certified copies at the interview. Follow the embassy's checklist and signature instructions: do not pre-sign DS-2029 or DS-11 when a witnessed signature is required; DS-3053 requires notarization and consent is generally submitted within 90 days. A U.S. address or tax return alone does not prove physical presence. Related-form intake uses the shared questionnaire you provided, not a substitute for official form instructions.": "Iwọnyi jẹ awọn ohun elo lọtọ, kii ṣe package ti o nilo gbogbo fọọmu. FS-240 jẹ ijẹrisi ti a fun, kii ṣe ohun elo kan. Pari faili lọtọ fun ọmọ kọọkan ki o fun awọn alaye obi kọọkan lọtọ. Awọn ọlọjẹ ko rọpo atilẹba tabi awọn ẹda ti a fọwọsi ni ifọrọwanilẹnuwo naa. Tẹle iwe ayẹwo ti ile-iṣẹ aṣoju ati awọn ilana ibuwọlu: ma ṣe ami-tẹlẹ DS-2029 tabi DS-11 nigbati o nilo ibuwọlu ẹlẹri; DS-3053 nbeere notarization ati igbanilaaye ti wa ni gbogbo silẹ laarin 90 ọjọ. Adirẹsi AMẸRIKA tabi ipadabọ owo-ori nikan ko ṣe afihan wiwa ti ara. Gbigbe fọọmu ti o jọmọ nlo iwe ibeere pinpin ti o pese, kii ṣe aropo fun awọn ilana fọọmu osise.",
  "Full name (as your electronic signature)": "Orukọ kikun (gẹgẹbi ibuwọlu itanna rẹ)",
  "I have read this declaration and I sign it and agree to all of it.": "Mo ti ka ìkéde yìí, mo sì fọwọ́ sí i, mo sì gba gbogbo rẹ̀.",
  "The NVC stage can only start after the USCIS petition stage is completed and approved (with us or elsewhere). Open a USCIS file first.": "Ipele NVC le bẹrẹ nikan lẹhin ipele ẹbẹ USCIS ti pari ati fọwọsi (pẹlu wa tabi ibomiiran). Ṣii faili USCIS ni akọkọ.",
  "The embassy stage can only start after the USCIS petition is approved and the NVC stage is complete (with us or elsewhere). Open a USCIS or NVC file first.": "Ipele ikọṣẹ le bẹrẹ lẹhin ti USCIS ti fọwọsi ẹbẹ ati pe ipele NVC ti pari (pẹlu wa tabi ibomiiran). Ṣii faili USCIS tabi NVC ni akọkọ.",
